use objc2_app_kit::NSPasteboard;
use objc2_foundation::NSString;

const PRIVATE_TYPES: [&str; 3] = [
    "org.nspasteboard.ConcealedType",
    "org.nspasteboard.TransientType",
    "org.nspasteboard.AutoGeneratedType",
];

pub(crate) fn change_count() -> isize {
    NSPasteboard::generalPasteboard().changeCount()
}

pub(crate) fn types() -> Vec<String> {
    NSPasteboard::generalPasteboard()
        .types()
        .map(|types| types.iter().map(|kind| kind.to_string()).collect())
        .unwrap_or_default()
}

pub(crate) fn is_private_type(kind: &str) -> bool {
    PRIVATE_TYPES.contains(&kind)
}

pub(crate) fn transform(text: &str, transform: &str) -> Option<String> {
    NSString::from_str(text)
        .stringByApplyingTransform_reverse(&NSString::from_str(transform), false)
        .map(|converted| converted.to_string())
}
